import{_ as e,o,c as s,ah as r}from"./chunks/framework.OBRqGMzg.js";const a="/SOARM101/projects/SOARM101/en/latest/assets/image_2.DoM9fOaO.png",i="/SOARM101/projects/SOARM101/en/latest/assets/image_3.DoFSlODw.png",n="/SOARM101/projects/SOARM101/en/latest/assets/image_4.BApGrYA5.png",g="data:image/png;base64,",c="/SOARM101/projects/SOARM101/en/latest/assets/image_5._u3z1X-I.png",l="/SOARM101/projects/SOARM101/en/latest/assets/image_6.DEZEw-vR.png",p="/SOARM101/projects/SOARM101/en/latest/assets/image_7.CuoClLHv.png",h="/SOARM101/projects/SOARM101/en/latest/assets/image_8.DvPw90xD.png",m="/SOARM101/projects/SOARM101/en/latest/assets/image_9.qWJ5pNOY.png",d="/SOARM101/projects/SOARM101/en/latest/assets/image_12.DBjxyB2N.png",A="/SOARM101/projects/SOARM101/en/latest/assets/image_11.C1XyzuJV.png",w="/SOARM101/projects/SOARM101/en/latest/assets/image_10.DXSNaKCY.png",b=JSON.parse('{"title":"Magnetic Encoder Servo Firmware Flashing Tutorial","description":"","frontmatter":{},"headers":[],"relativePath":"page/Magnetic Encoder Servo Firmware Flashing Tutorial.md","filePath":"page/Magnetic Encoder Servo Firmware Flashing Tutorial.md"}'),u={name:"page/Magnetic Encoder Servo Firmware Flashing Tutorial.md"};function z(f,t,S,M,O,k){return o(),s("div",null,[...t[0]||(t[0]=[r('<h1 id="magnetic-encoder-servo-firmware-flashing-tutorial" tabindex="-1">Magnetic Encoder Servo Firmware Flashing Tutorial <a class="header-anchor" href="#magnetic-encoder-servo-firmware-flashing-tutorial" aria-label="Permalink to &quot;Magnetic Encoder Servo Firmware Flashing Tutorial&quot;">​</a></h1><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>Taking HX-30HM as an example here,</strong></p></div><p><strong>Magnetic Encoder Servo</strong> PC Software Installation Package path: <a href="https://drive.google.com/drive/folders/1G2VSZiqwqcjcrp59oCFjL_C3VDzehWqo" target="_blank" rel="noreferrer">Appendix/ServoStudio_0.1.1_x64-setup.exe</a></p><p>The wiring diagram for the servo control board is shown below. Power the board with a 12V power supply and connect the servo control board to the computer using a Type-C cable. Connect the magnetic encoder servo to the board.</p><img loading="lazy" height="368" width="681" src="'+a+'" class="common_img" style="width:600px;"><p>Press <strong>Win+R</strong> to open the Control Panel, type <strong>devmgmt.msc</strong>, and open <strong>Device Manager</strong>.</p><img loading="lazy" height="206" width="399" src="'+i+'" class="common_img" style="width:500px;"><p>Click <strong>Ports</strong> to view the port number; here, the port number is <strong>COM10</strong>.</p><img loading="lazy" height="540" width="543" src="'+n+'" class="common_img" style="width:800px;"><p>Double-click to open the software <img loading="lazy" height="77" width="75" src="'+g+'" style="width:55px;">.</p><p>Follow the steps:<br> Change the <strong>Port</strong> number to the one found (in this case, change to <strong>COM10</strong>)<br> -&gt; Set the baud rate for <strong>HX-30HM</strong> to 1000000</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The baud rate may vary for different magnetic encoder servos. Refer to the corresponding model&#39;s user manual for specifics.</strong></p></div><p>-&gt; Click <strong>Connect</strong> -&gt; Click <strong>Scan</strong></p><img loading="lazy" height="902" width="1402" src="'+c+'" class="common_img" style="width:1200px;"><p>The system will scan all servo <code>ID</code>. If a servo is detected, a servo control interface will appear, as shown in the image below.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>If no servo is detected, unplug and re-plug the servo for testing.</strong></p></div><img loading="lazy" height="902" width="1402" src="'+l+'" class="common_img" style="width:1200px;"><p>Click <strong>Firmware</strong> -&gt; Click <strong>Click or drag firmware file here.</strong>.</p><img loading="lazy" height="1009" width="1920" src="'+p+'" class="common_img" style="width:1200px;"><p>Click the <strong>HX-30HM_V3.9_20251023.sfw</strong> firmware package -&gt; Click <strong>Open</strong>.</p><img loading="lazy" height="533" width="946" src="'+h+'" class="common_img" style="width:800px;"><p>Click <strong>Force Upgrade</strong> -&gt; Click <strong>Upgrade</strong>.</p><img loading="lazy" height="1009" width="1920" src="'+m+'" class="common_img" style="width:1200px;"><p>When the following screen appears, it indicates that the flashing process has started. At this point, unplug and re-plug the servo wire.</p><img loading="lazy" height="1009" width="1920" src="'+d+'" class="common_img" style="width:1200px;"><p>When the red box appears, it indicates the servo firmware has been successfully flashed.</p><img loading="lazy" height="1009" width="1920" src="'+A+'" class="common_img" style="width:1200px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>If a &quot;Handshake Failed&quot; message appears (as shown in the image below), follow the steps in the documentation to proceed again. Click &quot;Upgrade&quot; and retry the firmware flashing process.</strong></p></div><img loading="lazy" height="1009" width="1920" src="'+w+'" class="common_img" style="width:1200px;">',29)])])}const y=e(u,[["render",z]]);export{b as __pageData,y as default};
